scripts.sum_floor_divisions:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute sum of floor(A_i / B_i) for each position
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Compute N! mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

scripts.count_inversions:
def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Count pairs (i, j) where i < j and values[i] > values[j]
    count = 0
    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if values[i] > values[j]:
                count += 1

    return float(count)

